"""Generate reference documentation from the live registries (never hand-edit the generated files).

Produces:
  docs/OPERATIONS.md      every operation with parameters
  MCP_REFERENCE.md        MCP tools, resources and prompts with input schemas
  CLI_REFERENCE.md        `lazyroom` command tree with help texts
  docs/FILTER_PARITY.md   ImageToolbox filter-by-filter parity matrix (from docs/dev/port_reports)
  src/lazyroom/data/AGENT_GUIDE.md   copy of AGENT_INTEGRATION.md served as lazyroom://guide

Usage: python scripts/gen_docs.py
"""
from __future__ import annotations

import argparse
import asyncio
import json
import os
import re
import shutil
import sys
from collections import Counter, defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))
os.environ.setdefault("LAZYROOM_HOME", "/tmp/lazyroom-gendocs")

from lazyroom.core.registry import CATEGORIES, FILTER_GROUPS, all_ops  # noqa: E402

# Lead decisions recorded in the port reports' appendices (bug fixes over strict parity).
OVERRIDES = {
    "filter.gamma": ("approximate", "Upstream bug fixed: gamma applied to normalised values."),
    "filter.clahe_lab": ("approximate", "Upstream bug fixed: negative a*/b* no longer clamped."),
    "filter.clahe_luv": ("approximate", "Upstream bug fixed: negative u*/v* no longer clamped."),
    "filter.equalize_histogram_adaptive_lab": ("approximate", "Upstream bug fixed: negative a*/b* no longer clamped."),
    "filter.equalize_histogram_adaptive_luv": ("approximate", "Upstream bug fixed: negative u*/v* no longer clamped."),
    "filter.fish_eye": ("approximate", "Upstream bug fixed: radius/amplitude passed as G'MIC radius/amplitude."),
    "filter.moire": ("approximate", "Upstream bug fixed: real Butterworth filter (photos no longer garbled)."),
}


def md_escape(s: str) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def gen_operations() -> str:
    ops = all_ops()
    lines = ["# Operation catalogue", "", f"{len(ops)} operations (generated by `scripts/gen_docs.py`).",
             "Every operation can be used as a pipeline step from the MCP server, CLI, SDK and GUI.", ""]
    by_cat: dict[str, list] = defaultdict(list)
    for s in ops:
        by_cat[s.category].append(s)
    for cat in CATEGORIES:
        specs = sorted(by_cat.get(cat, []), key=lambda s: (s.group or "", s.id))
        if not specs:
            continue
        lines += [f"## {cat} — {CATEGORIES[cat]}", "", f"{len(specs)} operations.", ""]
        group = None
        for s in specs:
            if cat == "filter" and s.group != group:
                group = s.group
                lines += [f"### {FILTER_GROUPS.get(group, group)}", ""]
            req = f" — requires {', '.join(s.requires)}" if s.requires else ""
            geo = " — changes geometry" if s.geometry else ""
            lines.append(f"**`{s.id}`** — {md_escape(s.title)}{req}{geo}")
            if s.description:
                lines.append(f": {md_escape(s.description.splitlines()[0])[:300]}")
            if s.params:
                parts = []
                for p in s.params:
                    d = p.describe()
                    rng = f" {d['min']}..{d['max']}" if d.get("min") is not None and d.get("max") is not None else ""
                    if d.get("choices"):
                        ch = d["choices"]
                        rng = " {" + ", ".join(map(str, ch[:12])) + (", …" if len(ch) > 12 else "") + "}"
                    unit = f" {d['unit']}" if d.get("unit") else ""
                    parts.append(f"`{p.name}` ({d['type']}{rng}{unit}, default {json.dumps(d['default'])})")
                lines.append("  - params: " + "; ".join(parts))
            lines.append("")
    return "\n".join(lines) + "\n"


def gen_mcp() -> str:
    from lazyroom.mcp.server import INSTRUCTIONS, build_server

    server = build_server()
    tools = asyncio.run(server.list_tools())
    templates = asyncio.run(server.list_resource_templates())
    resources = asyncio.run(server.list_resources())
    prompts = asyncio.run(server.list_prompts())
    lines = ["# MCP reference", "", "Generated by `scripts/gen_docs.py` from the running server definition.", "",
             "Server name: `lazyroom`. Transports: stdio (`lazyroom-mcp`) and Streamable HTTP "
             "(`lazyroom mcp --transport http`, loopback + bearer token).", "", "## Server instructions", "",
             "```text", INSTRUCTIONS, "```", "", f"## Tools ({len(tools)})", ""]
    for t in tools:
        ann = t.annotations
        flags = []
        if ann is not None:
            if ann.read_only_hint:
                flags.append("read-only")
            if ann.destructive_hint:
                flags.append("destructive")
        lines += [f"### `{t.name}`" + (f"  _({', '.join(flags)})_" if flags else ""), "",
                  (t.description or "").strip(), "", "<details><summary>Input schema</summary>", "", "```json",
                  json.dumps(t.input_schema if hasattr(t, "input_schema") else t.inputSchema, indent=1), "```", "",
                  "</details>", ""]
    lines += ["## Resources", ""]
    for r in resources:
        lines.append(f"- `{r.uri}` — {r.description or r.name}")
    for r in templates:
        lines.append(f"- `{r.uri_template}` — {r.description or r.name}")
    lines += ["", "## Prompts", ""]
    for p in prompts:
        args = ", ".join(a.name for a in (p.arguments or []))
        lines.append(f"- `{p.name}({args})` — {p.title or p.description or ''}")
    lines += ["", "## Results and errors", "",
              "Successful calls return the JSON result as text content plus `structuredContent`; previews and "
              "comparisons add an inline `image/jpeg`. Failures return `isError: true` with "
              "`{\"error\": {\"code\", \"message\", \"details\", \"hint\"}}`.", ""]
    return "\n".join(lines) + "\n"


def gen_cli() -> str:
    from lazyroom.cli.main import build_parser

    parser = build_parser()
    lines = ["# CLI reference", "", "Generated by `scripts/gen_docs.py`. Output is JSON when stdout is not a "
             "terminal or with `--json` (`{\"ok\": true, \"result\": …}` / `{\"ok\": false, \"error\": …}`).", "",
             "Exit codes: 0 ok · 1 partial batch failure · 2 invalid input · 3 not found · 4 decode/encode · "
             "5 path/permission · 6 backend missing · 7 resource limit · 8 timeout · 9 cancelled · "
             "10 nothing to undo/redo · 11 operation failed · 70 internal error.", "", "```text",
             parser.format_help(), "```", ""]

    def walk(p: argparse.ArgumentParser, prefix: str) -> None:
        for action in p._actions:
            if isinstance(action, argparse._SubParsersAction):
                for name, sp in action.choices.items():
                    lines.extend([f"## `{prefix} {name}`", "", "```text", sp.format_help(), "```", ""])
                    walk(sp, f"{prefix} {name}")

    walk(parser, "lazyroom")
    return "\n".join(lines) + "\n"


def parse_reports() -> dict[str, dict]:
    rows: dict[str, dict] = {}
    for f in sorted((ROOT / "docs" / "dev" / "port_reports").glob("*.md")):
        for line in f.read_text().splitlines():
            cells = [c.strip() for c in line.strip().strip("|").split("|")]
            if len(cells) >= 4 and cells[1].strip("`").startswith("filter."):
                rows[cells[1].strip("`")] = {"filter": cells[0], "upstream": cells[2], "status": cells[3],
                                             "notes": cells[4] if len(cells) > 4 else "", "report": f.name}
    return rows


def gen_filter_parity() -> str:
    ops = {s.id: s for s in all_ops() if s.category == "filter"}
    reports = parse_reports()
    cat = json.loads((ROOT / "docs" / "dev" / "itb_catalog.json").read_text())
    from lazyroom.ops.itb._common import snake

    lines = ["# ImageToolbox filter parity matrix", "",
             "Generated by `scripts/gen_docs.py` from the registry and the per-group port reports in "
             "`docs/dev/port_reports/`. *faithful* = same algorithm as ImageToolbox (ported from its actual "
             "Kotlin/C++/Rust/GLSL/G'MIC sources); *approximate* = deviation explained in notes; "
             "*not ported* = missing.", "",
             "Every filter is an operation `filter.*` usable via MCP (`edit_project` / `apply_to_file`), CLI "
             "(`--op filter.x`), SDK and GUI (Filters category). Platform: pure Python/numpy/OpenCV/numba ports "
             "run wherever LazyRoom runs; G'MIC filters need the G'MIC CLI (bundled in release builds, or "
             "installed separately). Tests: `tests/itb/test_<group>.py` + `tests/test_ops_smoke.py` (every "
             "filter, defaults + parameter extremes + RGBA + determinism).", ""]
    counts: Counter = Counter()
    by_group: dict[str, list] = defaultdict(list)
    for o in cat:
        oid = f"filter.{snake(o['name'])}"
        spec = ops.get(oid)
        rep = reports.get(oid, {})
        status = rep.get("status", "faithful" if spec else "not ported")
        note = rep.get("notes", "")
        if oid in OVERRIDES:
            status, note = OVERRIDES[oid][0], OVERRIDES[oid][1] + " " + note
        if spec is None:
            status = "not ported"
        st = status.split()[0].lower()
        counts[st] += 1
        by_group[o["group"]].append((o["title"], oid if spec else "—", rep.get("upstream", o.get("backend", "")),
                                     status, ", ".join(spec.requires) if spec and spec.requires else "—", note))
    lines += ["| Status | Count |", "|---|---|"] + [f"| {k} | {v} |" for k, v in counts.most_common()]
    lines += [f"| **total** | **{sum(counts.values())}** |", ""]
    for g, title in FILTER_GROUPS.items():
        rows = sorted(by_group.get(g, []))
        lines += [f"## {title} ({len(rows)})", "", "| ImageToolbox filter | Operation | Implementation | Status | "
                  "Needs | Notes |", "|---|---|---|---|---|---|"]
        for t, oid, up, st, req, note in rows:
            lines.append(f"| {md_escape(t)} | `{oid}` | {md_escape(up)} | {md_escape(st)} | {req} | "
                         f"{md_escape(note)[:220]} |")
        lines.append("")
    return "\n".join(lines) + "\n"


def main() -> None:
    (ROOT / "docs").mkdir(exist_ok=True)
    (ROOT / "docs" / "OPERATIONS.md").write_text(gen_operations())
    (ROOT / "MCP_REFERENCE.md").write_text(gen_mcp())
    (ROOT / "CLI_REFERENCE.md").write_text(gen_cli())
    (ROOT / "docs" / "FILTER_PARITY.md").write_text(gen_filter_parity())
    shutil.copyfile(ROOT / "AGENT_INTEGRATION.md", ROOT / "src" / "lazyroom" / "data" / "AGENT_GUIDE.md")
    print("generated docs/OPERATIONS.md, MCP_REFERENCE.md, CLI_REFERENCE.md, docs/FILTER_PARITY.md, AGENT_GUIDE.md")


if __name__ == "__main__":
    main()
